formData.append('file', selectedFile);
formData.append('folder', 'avatars');

const res = await fetch('https://playground.nileslabs.com/api/v1/uploads', {
  method: 'POST',
  body: formData,
});

const data = await res.json();
console.log('CDN URL:', data.url);

